                    entities[field["id"]] = ("field", field)
                    owners[field["id"]] = entity["id"]
            if group == "behaviors":
                for inp in entity["inputs"]:
                    entities[inp["id"]] = ("input", inp)
                    owners[inp["id"]] = entity["id"]
                for contract in entity["guarantees"]:
                    if "id" in contract:
                        entities[contract["id"]] = ("postcondition", contract)
                        owners[contract["id"]] = entity["id"]
                for contract in entity["conditions"]:
                    if "id" in contract:
                        entities[contract["id"]] = ("precondition", contract)
                        owners[contract["id"]] = entity["id"]
    edges = defaultdict(set)

    def link(source, relation, target):
        if target in entities:
            edges[source].add((relation, target))

    for child, owner in owners.items():
        link(owner, "owns", child)
    for eid, (kind, entity) in entities.items():
        if kind in ("field", "input", "state"):
            link(eid, "type", entity["type"])
        if kind == "type":
            link(eid, "item_type", entity.get("item_type"))
        if kind == "state":
            link(eid, "storage", entity["storage"])
            link(eid, "key_field", entity["key_field"])
            for target in entity["invariants"]:
                link(eid, "constrained_by", target)
        if kind == "invariant":
            link(eid, "state", entity["state"])
            for target in [entity.get("field")] + [r["field"] for r in entity.get("field_rules", [])]:
                link(eid, "constrains_field", target)
            link(eid, "constrains_field", entity.get("predicate", {}).get("field"))
            link(eid, "constrains_query", entity.get("behavior"))
            link(eid, "constrains_lifecycle", entity.get("predicate", {}).get("machine"))
        if kind == "state_machine":
            link(eid, "lifecycle_field", entity["field"])
            for transition in entity["transitions"]:
                link(eid, "declares_transition", transition)
        if kind == "transition":
            link(eid, "machine", entity["machine"])
            link(eid, "guard", entity.get("guard"))
            link(eid, "trigger", entity["trigger"])
        if kind == "behavior":
            link(eid, "performs", entity.get("performs"))
            for grant in entity.get("requires", []):
                link(eid, "authorized_by", grant)
            link(eid, "state", entity["state"])
            link(eid, "output", entity["output"])
            if entity["kind"] == "create":
                link(eid, "creates", entity["output"])
            for target in entity["dependencies"]:
                link(eid, "depends_on", target)
            for relation in ("reads", "writes"):
                for target in entity[relation]:
                    link(eid, relation, target)
            for assignment in entity["assignments"]:
                link(eid, "assigns", assignment["field"])
                link(eid, "uses", assignment.get("id"))
            for target in entity.get("order_by", []):
                link(eid, "orders_by", target)
            if "filter" in entity:
                predicates = entity["filter"].get("predicates", [entity["filter"]])
                for predicate in predicates:
                    link(eid, "filters_by", predicate["field"])
                    if predicate["kind"] == "field_before_clock":
                        link(eid, "depends_on", predicate["clock"])
            if "lookup" in entity:
                link(eid, "looks_up", entity["lookup"]["field"])
                link(eid, "uses", entity["lookup"]["input"])
            for condition in entity["conditions"]:
                link(eid, "precondition_field", condition.get("field"))
                link(eid, "precondition_input", condition.get("input"))
        if kind == "postcondition":
            for relation in ("field", "state"):
                link(eid, relation, entity.get(relation))
        if kind == "precondition":
            for relation in ("field", "input"):
                link(eid, relation, entity.get(relation))
            link(eid, "fails_with", entity.get("failure"))
        if kind == "behavior":
            for failure in entity["failures"]:
                link(eid, "may_fail_with", failure)
        if kind == "command":
            link(eid, "exposes", entity.get("behavior", entity.get("migration")))
            for argument in entity["arguments"]:
                link(eid, "binds", argument["input"])
        if kind == "migration":
            for grant in entity.get("requires", []):
                link(eid, "authorized_by", grant)
            link(eid, "migrates", entity["state"])
            state = next(s for s in d["state"] if s["id"] == entity["state"])
            link(eid, "depends_on", state["storage"])
            for addition in entity["add_fields"]:
                link(eid, "adds_field", addition["field"])
        if kind == "scenario":
            link(eid, "tests", entity.get("behavior", entity.get("transition")))
            for field in (entity["record"] if "transition" in entity else entity["records"][0] if entity["records"] else ()):
                link(eid, "fixtures_field", field)
        if kind == "capability" and entity.get("kind") == "resource_access":
            link(eid, "authorizes_resource", entity["resource"])
    return entities, edges


def impact(program, eid):
    """Breadth-first reverse dependency traversal with one shortest path per entity.

    Ownership is traversed from child to parent: a field affects its record,
    never every sibling merely because the record owns them. Other edges are
    followed from target to source. Paths always point back to the root.
    """
    entities, edges = index(program)
    if eid not in entities:
        raise AirError(f"unknown entity ID: {eid}")
    reverse = defaultdict(list)
    for source, links in edges.items():
        for relation, target in links:
            reverse[target].append((source, relation))
    paths = {eid: []}
    queue = deque([eid])
    while queue:
        target = queue.popleft()
        for source, relation in sorted(reverse[target]):
            if source not in paths:
                paths[source] = [{"from": source, "relation": relation, "to": target}] + paths[target]
                queue.append(source)
    return {"root": eid, "impacts": [
        {"id": node, "kind": entities[node][0], "depth": len(path), "path": path,
         "classification": "direct" if len(path) == 1 else "indirect",
         "semantic_classification": classify(path)}
        for node, path in sorted(paths.items(), key=lambda pair: (len(pair[1]), pair[0])) if node != eid
    ]}


def classify(path):
    relations = {step["relation"] for step in path}
    if relations & {"performs", "declares_transition", "lifecycle_field", "machine", "trigger", "guard"}:
        return "TRANSITION_IMPACT"
    if relations & {"constrained_by", "constrains_field", "constrains_lifecycle", "constrains_query", "precondition_field"}:
        return "CONTRACT_IMPACT"
    if relations & {"authorized_by", "authorizes_resource"}:
        return "CAPABILITY_IMPACT"
    return "DIRECT_SEMANTIC_IMPACT" if len(path) == 1 else "DEPENDENCY_IMPACT"


def safety(program):
    """Evidence labels describe what was checked, never a numeric safety score."""
    validate(program)
    d = program.document
    findings = []
    for inv in d["invariants"]:
        kind = inv["kind"]
        evidence = "RUNTIME_ENFORCED"
        if kind == "query_exclusion":
            evidence = "STRUCTURALLY_GUARANTEED"  # Validator checks the closed-world equality filter.
        findings.append({"id": inv["id"], "evidence": evidence})
    relevant = []
    for behavior in d["behaviors"]:
        if not behavior["writes"]:
            continue
        mutated = {a["field"] for a in behavior["assignments"]}
        if behavior["kind"] in ("create", "delete"):
            mutated = {f["id"] for t in d["types"] if t["kind"] == "record" and t["id"] == behavior["output"] for f in t["fields"]}
        affected = [inv["id"] for inv in d["invariants"] if inv["state"] == behavior["state"] and (inv["kind"] in ("all_records_valid", "unique_field") and (inv.get("field") in mutated or any(r["field"] in mutated for r in inv.get("field_rules", []))) or inv["kind"] == "predicate" and inv["predicate"]["field"] in mutated or inv["kind"] == "query_exclusion" and inv["field"] in mutated)]
        relevant.append({"behavior": behavior["id"], "mutates": sorted(mutated), "relevant_invariants": affected})
    counts = {label: sum(f["evidence"] == label for f in findings) for label in ("STRUCTURALLY_GUARANTEED", "RUNTIME_ENFORCED", "SCENARIO_VERIFIED", "UNVERIFIED")}
    return {"state_machines": len(d.get("state_machines", [])), "declared_transitions": len(d.get("transitions", [])), "invalid_transitions": 0,
            "protected_resources": sum(c["kind"] == "json_file" for c in d["capabilities"]), "capability_violations": 0,
            "invariants": len(findings), "evidence_counts": counts, "findings": findings, "mutations": relevant}


def inspect(program, eid):
    entities, edges = index(program)
    if eid not in entities:
        raise AirError(f"unknown entity ID: {eid}")
    kind, entity = entities[eid]
    return {"id": eid, "kind": kind, "entity": entity,
            "dependencies": [{"relation": r, "id": t} for r, t in sorted(edges[eid])],
            "references": [{"relation": r, "id": source} for source, links in sorted(edges.items()) for r, t in sorted(links) if t == eid],
            "effects": entity.get("effects", []) if kind in ("behavior", "migration") else []}


def diff(before, after):
    left, left_edges = index(before)
    right, right_edges = index(after)
    changes = []
    for eid in sorted(left.keys() | right.keys()):
        if eid not in left:
            changes.append({"entity_id": eid, "kind": right[eid][0], "change": "added"})
        elif eid not in right:
            changes.append({"entity_id": eid, "kind": left[eid][0], "change": "removed"})
        elif left[eid] != right[eid]:
            old, new = left[eid][1], right[eid][1]
            attributes = sorted(key for key in old.keys() | new.keys() if old.get(key) != new.get(key))
            changes.append({"entity_id": eid, "kind": right[eid][0], "change": "modified", "attributes": attributes})
    for eid in sorted(left.keys() & right.keys()):
        for relation, target in sorted(right_edges[eid] - left_edges[eid]):
            changes.append({"entity_id": eid, "change": "dependency_added", "relation": relation, "target": target})
        for relation, target in sorted(left_edges[eid] - right_edges[eid]):
            changes.append({"entity_id": eid, "change": "dependency_removed", "relation": relation, "target": target})
    changed = {c["entity_id"] for c in changes}
    affected = {}
    for eid in sorted(right):
        causes = sorted({target for _, target in right_edges[eid] if target in changed})
        if eid in changed or causes:
            affected[eid] = {"direct": eid in changed, "via": causes}
    return {"before_version": before.version, "after_version": after.version,
            "changes": changes, "affected": affected}

"""Python backend template. Emitted into a self-contained generated application."""

import argparse
from datetime import datetime, timezone
import json
import os
from pathlib import Path
import sys
import tempfile
from uuid import uuid4


SPEC = {}  # AXIOM_SPEC_INSERTION_POINT


class Failure(Exception):
    def __init__(self, code):
        self.code = next((e["code"] for e in SPEC.get("errors", []) if e["id"] == code), code)
        super().__init__(code)


def by_id(group, eid):
    return next(item for item in SPEC[group] if item["id"] == eid)


def field_name(record_type, field_id):
    return next(f["name"] for f in record_type["fields"] if f["id"] == field_id)


def state_layout(state):
    list_type = by_id("types", state["type"])
    record_type = by_id("types", list_type["item_type"])
    return record_type, Path(by_id("capabilities", state["storage"])["path"])


def utc_timestamp(value):
    if not isinstance(value, str) or not value.endswith("Z"):
        return False
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
        return dt.tzinfo is not None and dt.utcoffset().total_seconds() == 0
    except ValueError:
        return False


def valid_state(records, state, record_type):
    if not isinstance(records, list):
        return False
    fields = record_type["fields"]
    for record in records:
        if not isinstance(record, dict) or set(record) != {f["name"] for f in fields}:
            return False
        for f in fields:
            value = record[f["name"]]
            typ = f["type"]
            if value is None and f.get("nullable", False):
                continue
            if typ in ("prim:string", "prim:timestamp"):
                if not isinstance(value, str) or (typ == "prim:timestamp" and not utc_timestamp(value)):
                    return False
            elif value not in by_id("types", typ)["values"]:
                return False
    for iid in state["invariants"]:
        inv = by_id("invariants", iid)
        if inv["kind"] == "unique_field":
            name = field_name(record_type, inv["field"])
            if len({r[name] for r in records}) != len(records):
                return False
        elif inv["kind"] == "all_records_valid":
            for rule in inv["field_rules"]:
                name = field_name(record_type, rule["field"])
                if rule["kind"] == "nonblank" and any(not r[name].strip() for r in records):
                    return False
                if rule["kind"] == "timestamp_utc" and any(r[name] is not None and not utc_timestamp(r[name]) for r in records):
                    return False
        elif inv["kind"] == "predicate":
            pred = inv["predicate"]
            name = field_name(record_type, pred["field"])
            if pred["operator"] == "NOT_EMPTY" and any(not r[name].strip() for r in records):
                return False
            if pred["operator"] == "IN" and any(r[name] not in pred["values"] for r in records):
                return False
            if pred["operator"] == "LIFECYCLE_STATE":
                machine = by_id("state_machines", pred["machine"])
                values = by_id("types", next(f["type"] for f in record_type["fields"] if f["id"] == pred["field"]))["values"]
                if any(r[name] not in values for r in records):
                    return False
    return True


def decode_state(payload, state):
    if "schema_version" not in state:
        return payload
    if state["schema_version"] == 1 and isinstance(payload, list):
        return payload
    if not isinstance(payload, dict) or payload.get("schema_version") != state["schema_version"]:
        raise Failure("migration_required")
    if set(payload) != {"schema_version", "records"}:
        raise Failure("invalid_state")
    return payload.get("records")


def read_state(state, record_type, path):
    try:
        with path.open(encoding="utf-8") as source:
            records = decode_state(json.load(source), state)
    except FileNotFoundError:
        if path.exists():
            raise Failure("persistence_failure")
        records = []
    except (json.JSONDecodeError, UnicodeError) as exc:
        raise Failure("invalid_state") from exc
    except OSError as exc:
        raise Failure("persistence_failure") from exc
    if not valid_state(records, state, record_type):
        raise Failure("invalid_state")
    return records


def write_state(records, state, record_type, path):
    if not valid_state(records, state, record_type):
        raise Failure("invalid_state")
    temp_path = None
    try:
        with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", dir=path.parent, prefix=".axiom-", suffix=".tmp", delete=False) as dest:
            temp_path = Path(dest.name)
            payload = {"schema_version": state["schema_version"], "records": records} if "schema_version" in state and state["schema_version"] > 1 else records
            json.dump(payload, dest, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
            dest.write("\n")
        os.replace(temp_path, path)
    except OSError as exc:
        raise Failure("persistence_failure") from exc
    finally:
        if temp_path is not None:
            temp_path.unlink(missing_ok=True)


def value_of(assignment, inputs):
    if assignment["source"] == "literal":
        return assignment["value"]
    if assignment["source"] == "input":
        return inputs[assignment["id"]]
    if assignment["source"] == "input_default":
        return inputs.get(assignment["id"], assignment["value"])
    kind = by_id("capabilities", assignment["id"])["kind"]
    if kind == "uuid_v4":
        return str(uuid4())
    if kind == "utc_clock":
        return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    raise AssertionError("unvalidated capability")


def sorted_records(records, behavior, record_type):
    keys = [field_name(record_type, fid) for fid in behavior["order_by"]]
    return sorted(records, key=lambda record: tuple(record[k] for k in keys))


def clock_value():
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def select_records(records, behavior, record_type, now):
    if "filter" not in behavior:
        return records
    spec = behavior["filter"]
    predicates = spec["predicates"] if spec["kind"] == "all" else [spec]
    def matches(record):
        for predicate in predicates:
            value = record[field_name(record_type, predicate["field"])]
            if predicate["kind"] == "field_equals":
                ok = value == predicate["value"]
            elif predicate["kind"] == "field_before_clock":
                ok = value is not None and datetime.fromisoformat(value.replace("Z", "+00:00")) < datetime.fromisoformat(now.replace("Z", "+00:00"))
            else:
                raise AssertionError("unvalidated predicate")
            if not ok:
                return False
        return True
    return [record for record in records if matches(record)]


def check_guarantees(behavior, result, records, state, record_type, inputs, now=None):
    key = field_name(record_type, state["key_field"])
    for guarantee in behavior["guarantees"]:
        kind = guarantee["kind"]
        if kind == "result_field_equals":
            ok = result[field_name(record_type, guarantee["field"])] == guarantee["value"]
        elif kind == "result_field_equals_assignment":
            assignment = next(a for a in behavior["assignments"] if a["field"] == guarantee["field"])
            ok = result[field_name(record_type, guarantee["field"])] == value_of(assignment, inputs)
        elif kind == "result_in_state":
            ok = any(r[key] == result[key] and r == result for r in records)
        elif kind == "result_id_absent_from_state":
            ok = all(r[key] != result[key] for r in records)
        elif kind == "result_equals_state_sorted":
            selection = select_records(records, behavior, record_type, now)
            ok = result == sorted_records(selection, behavior, record_type)
        else:
            raise AssertionError("unvalidated guarantee")
        if not ok:
            raise AssertionError(f"Axiom guarantee violated: {behavior['id']} {kind}")


def execute(behavior, inputs, clock=None):
    state = by_id("state", behavior["state"])
    record_type, path = state_layout(state)
    records = read_state(state, record_type, path)
    key = field_name(record_type, state["key_field"])
    target = None
    if "lookup" in behavior:
        lookup = behavior["lookup"]
        target = next((r for r in records if r[key] == inputs[lookup["input"]]), None)
    for condition in behavior["conditions"]:
        kind = condition["kind"]
        if kind == "nonblank_input":
            ok = bool(inputs[condition["input"]].strip())
        elif kind == "record_exists":
            ok = target is not None
        elif kind == "record_field_equals":
            ok = target[field_name(record_type, condition["field"])] == condition["value"]
        elif kind == "timestamp_input":
            value = inputs.get(condition["input"])
            ok = value is None or utc_timestamp(value)
        else:
            raise AssertionError("unvalidated condition")
        if not ok:
            raise Failure(condition["failure"])
    kind = behavior["kind"]
    now = (clock or clock_value)() if "clock_read" in behavior["effects"] and kind == "list" else None
    if kind == "list":
        selection = select_records(records, behavior, record_type, now)
        result = sorted_records(selection, behavior, record_type)
    elif kind == "create":
        result = {field_name(record_type, a["field"]): value_of(a, inputs) for a in behavior["assignments"]}
        if any(r[key] == result[key] for r in records):
            raise Failure("id_collision")
        records.append(result)
    elif kind == "update":
        if "performs" in behavior:
            transition = by_id("transitions", behavior["performs"])
            machine = by_id("state_machines", transition["machine"])
            if target[field_name(record_type, machine["field"])] != transition["source"]:
                guard = next(c for c in behavior["conditions"] if c["id"] == transition["guard"])
                raise Failure(guard["failure"])
        for a in behavior["assignments"]:
            target[field_name(record_type, a["field"])] = value_of(a, inputs)
        result = target.copy()
    elif kind == "delete":
        result = target.copy()
        records.remove(target)
    else:
        raise AssertionError("unvalidated behavior")
    if not valid_state(records, state, record_type):
        raise Failure("invalid_state")
    check_guarantees(behavior, result, records, state, record_type, inputs, now)
    if kind != "list":
        write_state(records, state, record_type, path)
    return result


def migrate():
    migrations = sorted(SPEC["migrations"], key=lambda item: item["from_version"])
    state = by_id("state", migrations[0]["state"])
    record_type, path = state_layout(state)
    try:
        with path.open(encoding="utf-8") as source:
            payload = json.load(source)
    except FileNotFoundError:
        return {"migrated": 0}
    except (json.JSONDecodeError, UnicodeError) as exc:
        raise Failure("invalid_state") from exc
    except OSError as exc:
        raise Failure("persistence_failure") from exc
    if isinstance(payload, dict) and payload.get("schema_version") == state["schema_version"]:
        if set(payload) != {"schema_version", "records"}:
            raise Failure("invalid_state")
        if not valid_state(payload.get("records"), state, record_type):
            raise Failure("invalid_state")
        return {"migrated": 0}
    version = 1 if isinstance(payload, list) else payload.get("schema_version") if isinstance(payload, dict) else None
    records = payload if version == 1 else payload.get("records") if isinstance(payload, dict) else None
    if not isinstance(records, list):
        raise Failure("invalid_state")
    for migration in migrations:
        if migration["from_version"] != version:
            continue
        added = {field_name(record_type, a["field"]): a["value"] for a in migration["add_fields"]}
        remaining = {field_name(record_type, a["field"]) for step in migrations if step["from_version"] >= version for a in step["add_fields"]}
        old_fields = {f["name"] for f in record_type["fields"]} - remaining
        if any(not isinstance(r, dict) or set(r) != old_fields for r in records):
            raise Failure("invalid_state")
        records = [{**r, **added} for r in records]
        version = migration["to_version"]
    if version != state["schema_version"] or not valid_state(records, state, record_type):
        raise Failure("invalid_state")
    write_state(records, state, record_type, path)
    return {"migrated": len(records)}


def main(argv=None):
    parser = argparse.ArgumentParser(prog=SPEC["application"]["name"])
    commands = parser.add_subparsers(dest="command", required=True)
    for command in SPEC["commands"]:
        sub = commands.add_parser(command["token"])
        if "migration" in command:
            continue
        behavior = by_id("behaviors", command["behavior"])
        for arg in command["arguments"]:
            inp = next(i for i in behavior["inputs"] if i["id"] == arg["input"])
            choices = by_id("types", inp["type"])["values"] if inp["type"] not in ("prim:string", "prim:timestamp") else None
            sub.add_argument(arg["flag"], required=arg["required"], choices=choices)
    parsed = parser.parse_args(argv)
    command = next(c for c in SPEC["commands"] if c["token"] == parsed.command)
    if "migration" in command:
        try:
            result = migrate()
        except Failure as exc:
            print(json.dumps({"error": exc.code}), file=sys.stderr)
            return 1
        print(json.dumps(result, sort_keys=True))
        return 0
    behavior = by_id("behaviors", command["behavior"])
    inputs = {a["input"]: value for a in command["arguments"] if (value := getattr(parsed, a["flag"][2:].replace("-", "_"))) is not None}
    try:
        result = execute(behavior, inputs)
    except Failure as exc:
        print(json.dumps({"error": exc.code}), file=sys.stderr)
        return 1
    print(json.dumps(result, sort_keys=True, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())

